CREATE TABLE "PlanProviderBenefit" ("id" TEXT NOT NULL,"planId" TEXT NOT NULL,"providerId" TEXT NOT NULL,"discountType" "DiscountType" NOT NULL DEFAULT 'PERCENT',"discountValue" DECIMAL(12,2) NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PlanProviderBenefit_pkey" PRIMARY KEY ("id"),CONSTRAINT "PlanProviderBenefit_planId_fkey" FOREIGN KEY ("planId") REFERENCES "BenefitPlan"("id"),CONSTRAINT "PlanProviderBenefit_providerId_fkey" FOREIGN KEY ("providerId") REFERENCES "Provider"("id"));
CREATE UNIQUE INDEX "PlanProviderBenefit_planId_providerId_key" ON "PlanProviderBenefit"("planId","providerId");
CREATE INDEX "PlanProviderBenefit_providerId_isActive_idx" ON "PlanProviderBenefit"("providerId","isActive");
